ST.xhtml:p:
(*开浮动*)
RTrigger1(CLK := g_bSustain1Follow OR bSustain1Follow);
RTrigger2(CLK := g_bSustain2Follow OR bSustain2Follow);
RTrigger3(CLK := g_bSustain3Follow OR bSustain3Follow);
RTrigger7(CLK := g_bSustain7Follow OR bSustain7Follow);
RTrigger8(CLK := g_bSustain8Follow OR bSustain8Follow);
RTrigger9(CLK := g_bSustain9Follow OR bSustain9Follow);

(*关浮动*)
FTrigger1(CLK := g_bSustain1Follow OR bSustain1Follow );
FTrigger2(CLK := g_bSustain2Follow OR bSustain2Follow);
FTrigger3(CLK := g_bSustain3Follow OR bSustain3Follow);
FTrigger7(CLK := g_bSustain7Follow OR bSustain7Follow);
FTrigger8(CLK := g_bSustain8Follow OR bSustain8Follow);
FTrigger9(CLK := g_bSustain9Follow OR bSustain9Follow);

IF RTrigger1.Q THEN
  IF g_bSustain1Follow THEN
    nFollowState1 := 1;
  ELSE
    nFollowState1 := 2;
  END_IF;
END_IF;
IF RTrigger2.Q THEN
  IF g_bSustain2Follow THEN
    nFollowState2 := 1;
  ELSE
    nFollowState2 := 2;
  END_IF;
END_IF;
IF RTrigger3.Q THEN
  IF g_bSustain3Follow THEN
    nFollowState3 := 1;
  ELSE
    nFollowState3 := 2;
  END_IF;
END_IF;
IF RTrigger7.Q THEN
  IF g_bSustain7Follow THEN
    nFollowState7 := 1;
  ELSE
    nFollowState7 := 2;
  END_IF;
END_IF;
IF RTrigger8.Q THEN
  IF g_bSustain8Follow THEN
    nFollowState8 := 1;
  ELSE
    nFollowState8 := 2;
  END_IF;
END_IF;
IF RTrigger9.Q THEN
 IF g_bSustain9Follow THEN
    nFollowState9 := 1;
  ELSE
    nFollowState9 := 2;
  END_IF;
END_IF;

IF FTrigger1.Q THEN
  nFollowState1 := 3;
END_IF;
IF FTrigger2.Q THEN
  nFollowState2 := 3;
END_IF;
IF FTrigger3.Q THEN
  nFollowState3 := 3;
END_IF;
IF FTrigger7.Q THEN
  nFollowState7 := 3;
END_IF;
IF FTrigger8.Q THEN
  nFollowState8 := 3;
END_IF;
IF FTrigger9.Q THEN
  nFollowState9 := 3;
END_IF;

g_SustainFollowIn1.CurHeight := 1.0;
g_SustainFollowIn2.CurHeight := 1.0;
g_SustainFollowIn3.CurHeight := 1.0;
g_SustainFollowIn7.CurHeight := 1.0;
g_SustainFollowIn8.CurHeight := 1.0;
g_SustainFollowIn9.CurHeight := 1.0;
g_SustainFollowIn1.SetHeight := g_SustainFollowIn1.CurHeight;
g_SustainFollowIn2.SetHeight := g_SustainFollowIn2.CurHeight;
g_SustainFollowIn3.SetHeight := g_SustainFollowIn3.CurHeight;
g_SustainFollowIn7.SetHeight := g_SustainFollowIn7.CurHeight;
g_SustainFollowIn8.SetHeight := g_SustainFollowIn8.CurHeight;
g_SustainFollowIn9.SetHeight := g_SustainFollowIn9.CurHeight;
fSetPos := g_fSustainTargetPos;
g_SustainFollowIn1.Distance := -(fSetPos - dLastCoord);
g_SustainFollowIn2.Distance := -(fSetPos - dLastCoord);
g_SustainFollowIn3.Distance := -(fSetPos - dLastCoord);
g_SustainFollowIn7.Distance := -(fSetPos - dLastCoord);
g_SustainFollowIn8.Distance := -(fSetPos - dLastCoord);
g_SustainFollowIn9.Distance := -(fSetPos - dLastCoord);
dLastCoord := fSetPos;

CASE nFollowState1 OF
  0:
    nFollowState1 := 0;
  1:
    g_SustainFollowIn1.Execute := TRUE;
    IF g_SustainFollowIn1.Done THEN
      g_bSustain1InFollow := TRUE;
    END_IF;
    IF g_SustainFollowIn1.Error THEN
      (*IF g_SustainFollowIn1.ErrorId = 112 THEN
         ;
      END_IF;*)
      g_bSustain1InFollow := FALSE;
      g_SustainFollowIn1.Execute := FALSE;
      nFollowState1 := 0;
    END_IF;
  2:
    IF g_bSustain1AbsDone THEN
      nFollowState1 := 1; 
    END_IF;
  3:
    g_SustainFollowOut1.Execute := TRUE;
    g_SustainFollowIn1.Execute := FALSE;
    IF g_SustainFollowOut1.Done OR g_SustainFollowOut1.Error THEN
      g_bSustain1InFollow := FALSE;
      g_SustainFollowOut1.Execute := FALSE;
      nFollowState1 := 0;
    END_IF;
END_CASE;

