IF g_bPlcResetBuffer THEN
  g_SustainFollowIn1.Execute := FALSE;
  g_SustainFollowIn2.Execute := FALSE;
  g_SustainFollowIn3.Execute := FALSE;
  g_SustainFollowIn7.Execute := FALSE;
  g_SustainFollowIn8.Execute := FALSE;
  g_SustainFollowIn9.Execute := FALSE;
  g_SustainFollowOut1.Execute := FALSE;
  g_SustainFollowOut2.Execute := FALSE;
  g_SustainFollowOut3.Execute := FALSE;
  g_SustainFollowOut7.Execute := FALSE;
  g_SustainFollowOut8.Execute := FALSE;
  g_SustainFollowOut9.Execute := FALSE;
  g_bSustain1InFollow := FALSE;
  g_bSustain2InFollow := FALSE;
  g_bSustain3InFollow := FALSE;
  g_bSustain7InFollow := FALSE;
  g_bSustain8InFollow := FALSE;
  g_bSustain9InFollow := FALSE;
END_IF;
